values
('egg-fried-rice', '계란 볶음밥', '남은 밥과 계란만 있으면 10분 안에 완성하는 한 그릇 요리', '/recipe-placeholder.svg', ARRAY['계란', '양파', '대파', '밥']::text[], '쉬움', 15, '간단식', '발행', '2026-10-01'::timestamptz, '[{"name":"밥","amount":"1공기"},{"name":"계란","amount":"2개"},{"name":"양파","amount":"1/4개"},{"name":"대파","amount":"5cm"}]'::jsonb, '[{"order":1,"text":"양파와 대파를 잘게 썬다."},{"order":2,"text":"달군 팬에 기름을 두르고 계란을 스크램블한 뒤 꺼낸다."},{"order":3,"text":"같은 팬에 양파와 대파를 볶다가 밥을 넣고 볶는다."},{"order":4,"text":"계란을 다시 넣고 간장으로 간을 맞춰 마무리한다."}]'::jsonb),
('tofu-doenjang-stew', '두부 된장찌개', '멸치 육수에 된장을 풀어 끓이는 가장 기본적인 한식 찌개', '/recipe-placeholder.svg', ARRAY['두부', '양파', '애호박', '된장']::text[], '쉬움', 20, '한식', '발행', '2026-10-03'::timestamptz, '[{"name":"두부","amount":"1/2모"},{"name":"된장","amount":"1큰술"},{"name":"애호박","amount":"1/4개"},{"name":"양파","amount":"1/4개"}]'::jsonb, '[{"order":1,"text":"물에 된장을 풀고 끓기 시작하면 양파와 애호박을 넣는다."},{"order":2,"text":"채소가 익으면 깍둑썬 두부를 넣고 2분 더 끓인다."},{"order":3,"text":"대파와 고추를 올려 마무리한다."}]'::jsonb),
('egg-tomato-scramble', '계란 토마토 스크램블', '토마토의 산미가 살아 있는 부드러운 양식풍 계란 요리', '/recipe-placeholder.svg', ARRAY['계란', '토마토', '양파']::text[], '쉬움', 10, '양식', '발행', '2026-10-05'::timestamptz, '[{"name":"계란","amount":"2개"},{"name":"토마토","amount":"1개"},{"name":"양파","amount":"1/4개"}]'::jsonb, '[{"order":1,"text":"토마토와 양파를 한입 크기로 썬다."},{"order":2,"text":"팬에 양파를 볶다가 토마토를 넣고 수분이 줄 때까지 익힌다."},{"order":3,"text":"풀어 둔 계란을 넣고 천천히 저어 부드럽게 익힌다."}]'::jsonb),
('chicken-breast-salad', '닭가슴살 샐러드', '삶은 닭가슴살과 채소를 올린 가볍고 든든한 샐러드', '/recipe-placeholder.svg', ARRAY['닭가슴살', '양상추', '토마토']::text[], '보통', 25, '양식', '발행', '2026-10-07'::timestamptz, '[{"name":"닭가슴살","amount":"1쪽"},{"name":"양상추","amount":"한 줌"},{"name":"토마토","amount":"1/2개"},{"name":"올리브유","amount":"1작은술"}]'::jsonb, '[{"order":1,"text":"닭가슴살을 소금과 후추로 간해 15분 재운다."},{"order":2,"text":"팬에 올리브유를 두르고 닭가슴살을 중불에서 익힌 뒤 한입 크기로 자른다."},{"order":3,"text":"양상추와 토마토를 그릇에 담고 닭가슴살을 올려 완성한다."}]'::jsonb),
('kimchi-fried-rice', '김치 볶음밥', '잘 익은 김치와 밥을 볶아 만드는 간단한 한 끼', '/recipe-placeholder.svg', ARRAY['김치', '밥', '계란', '대파']::text[], '쉬움', 15, '한식', '발행', '2026-10-08'::timestamptz, '[{"name":"밥","amount":"1공기"},{"name":"김치","amount":"1/2컵"},{"name":"계란","amount":"1개"},{"name":"대파","amount":"5cm"}]'::jsonb, '[{"order":1,"text":"김치와 대파를 잘게 썬다."},{"order":2,"text":"팬에 김치를 볶아 기름과 향을 낸다."},{"order":3,"text":"밥을 넣고 김치와 함께 볶은 뒤 계란 프라이를 올린다."}]'::jsonb),
('tuna-mayo-rice-ball', '참치 마요 주먹밥', '도시락이나 간식으로 좋은 김 주먹밥', '/recipe-placeholder.svg', ARRAY['참치', '밥', '김']::text[], '쉬움', 10, '간단식', '발행', '2026-10-10'::timestamptz, '[{"name":"밥","amount":"1공기"},{"name":"참치캔","amount":"1/2캔"},{"name":"마요네즈","amount":"1큰술"},{"name":"김","amount":"1장"}]'::jsonb, '[{"order":1,"text":"참치의 기름을 빼고 마요네즈와 섞는다."},{"order":2,"text":"밥에 참치마요를 넣고 삼각형으로 뭉친다."},{"order":3,"text":"김을 감싸서 완성한다."}]'::jsonb),
('bacon-cream-pasta', '베이컨 크림 파스타', '우유와 치즈로 간단하게 만드는 크리미한 파스타', '/recipe-placeholder.svg', ARRAY['베이컨', '양파', '우유', '파스타 면']::text[], '보통', 30, '양식', '발행', '2026-10-12'::timestamptz, '[{"name":"파스타 면","amount":"100g"},{"name":"베이컨","amount":"2줄"},{"name":"양파","amount":"1/4개"},{"name":"우유","amount":"150ml"}]'::jsonb, '[{"order":1,"text":"파스타 면을 소금물에 알 덴테로 삶는다."},{"order":2,"text":"베이컨과 양파를 볶아 향을 낸다."},{"order":3,"text":"우유를 넣고 약불에서 졸인 뒤 면을 넣어 버무린다."}]'::jsonb),
('beef-seaweed-soup', '소고기 미역국', '참기름에 소고기를 볶아 우려낸 생일 대표 한식 국', '/recipe-placeholder.svg', ARRAY['소고기', '미역', '참기름']::text[], '보통', 40, '한식', '발행', '2026-10-14'::timestamptz, '[{"name":"소고기 양지","amount":"80g"},{"name":"미역","amount":"10g"},{"name":"참기름","amount":"1큰술"},{"name":"국간장","amount":"1작은술"}]'::jsonb, '[{"order":1,"text":"미역을 물에 불려 한입 크기로 자른다."},{"order":2,"text":"냄비에 참기름을 두르고 소고기를 볶은 뒤 미역을 넣고 함께 볶는다."},{"order":3,"text":"물을 붓고 20분 끓인 뒤 국간장으로 간을 맞춘다."}]'::jsonb),
('potato-bacon-saute', '감자 베이컨 볶음', '감자와 베이컨을 함께 볶아 밥반찬으로 좋은 요리', '/recipe-placeholder.svg', ARRAY['감자', '베이컨', '양파']::text[], '쉬움', 20, '간단식', '발행', '2026-10-15'::timestamptz, '[{"name":"감자","amount":"1개"},{"name":"베이컨","amount":"2줄"},{"name":"양파","amount":"1/4개"}]'::jsonb, '[{"order":1,"text":"감자는 얇게 썰어 전자레인지에 3분 익힌다."},{"order":2,"text":"팬에 베이컨을 볶아 기름이 나오면 감자와 양파를 넣는다."},{"order":3,"text":"노릇하게 볶아 후추로 간한다."}]'::jsonb),
('steamed-egg-custard', '대파 달걀찜', '부드럽고 고소한 한식 계란찜', '/recipe-placeholder.svg', ARRAY['계란', '대파']::text[], '쉬움', 15, '한식', '발행', '2026-10-16'::timestamptz, '[{"name":"계란","amount":"2개"},{"name":"물","amount":"120ml"},{"name":"대파","amount":"5cm"},{"name":"새우젓","amount":"1/2작은술"}]'::jsonb, '[{"order":1,"text":"계란을 풀고 물과 새우젓을 넣어 체에 한 번 거른다."},{"order":2,"text":"대파를 잘게 썰어 계란물에 넣는다."},{"order":3,"text":"뚜껑을 덮고 중약불에서 7분간 찐다."}]'::jsonb)
